import{_ as r}from"./chunks/ba14c3244bd4e60f10c2.5G1arqt5.js";import{_ as a}from"./chunks/b83af1bd150d367db386.ZfewuIjW.js";import{_ as o,C as l,o as i,c as n,j as t,a as s,E as m,a6 as c}from"./chunks/framework.CnPv4DE1.js";const v=JSON.parse('{"title":"如何作为创作者在互联网上赚钱","description":"","frontmatter":{"title":"如何作为创作者在互联网上赚钱","originalTitle":"How To Make Money As A Creative On The Internet","date":"2022-06-11","originalUrl":"https://thedankoe.com/letters/how-to-make-money-as-a-creative-on-the-internet/","minutes":12,"sourceHash":"d92739642d1bdd95d32d181fb8fffe793761fa820ee8f58d7eea8381bf95df04","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-make-money-as-a-creative-on-the-internet/"}]]},"headers":[],"relativePath":"letters/how-to-make-money-as-a-creative-on-the-internet.md","filePath":"letters/how-to-make-money-as-a-creative-on-the-internet.md"}'),h={name:"letters/how-to-make-money-as-a-creative-on-the-internet.md"};function f(g,e,d,u,k,_){const p=l("ArticleMeta");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"如何作为创作者在互联网上赚钱",tabindex:"-1"},[s("如何作为创作者在互联网上赚钱 "),t("a",{class:"header-anchor",href:"#如何作为创作者在互联网上赚钱","aria-label":'Permalink to "如何作为创作者在互联网上赚钱"'},"​")],-1)),m(p),e[1]||(e[1]=c('<p><a href="https://www.youtube.com/embed/V_oZNWJKPZI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>人类是懒惰的。</p><p>在整个人类进化史中，我们一直在创造各种解决方案，让生活变得更轻松。</p><p>有时，这是需要付出代价的。逐步淘汰体力劳动岗位，是我们历史上的一个常见主题。</p><p>我们不喜欢犁地。随着人口不断增长，这不仅不可持续，而且几乎不可能规模化。</p><p>因此，在几十年的时间里，我们创造了机器、拖拉机、分销网络、转基因作物以及许多其他东西，这为创造力腾出了更多空间。</p><p>前几天刷推特的时候，我看到了这条推文。</p><blockquote><p>亚利桑那州马拉纳的麦当劳取消了人类收银员——你唯一的选择就是自助点餐机。这是我们社会的巨大倒退。点57美元的食物要花20分钟（在乔·拜登的经济下，一个四分之一磅汉堡，单点不带套餐，要6.50美元！）。把人类带回来吧 <a href="https://t.co/eSigaCA3NZ" target="_blank" rel="noreferrer">pic.twitter.com/eSigaCA3NZ</a></p><p>— Blake Masters (@bgmasters) <a href="https://twitter.com/bgmasters/status/1533948876935139328?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 6, 2022</a></p></blockquote><p>撇开政治不谈，这并不是什么新鲜事。这一天早就该来了。</p><p>低技能劳动岗位正在被淘汰。历史一次又一次地证明了这种模式。我们无法逃避这个进化阶段。</p><blockquote><p>如果工作不需要创造力，要么把它外包，要么把它自动化，要么就离开它。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1311199771676176384?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">September 30, 2020</a></p></blockquote><p>人们已经在这么做了。</p><p>如果一项工作不需要创造力，你可以拿你的未来打赌，它肯定会被外包、自动化或淘汰。</p><p>你只有一个选择：为自己的未来承担责任，并坚持不懈地自我教育。</p><h2 id="要么去创造-要么被创造" tabindex="-1">要么去创造，要么被创造 <a class="header-anchor" href="#要么去创造-要么被创造" aria-label="Permalink to &quot;要么去创造，要么被创造&quot;">​</a></h2><p>意识是现实的基石。<a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">为意识赋予秩序的能力是21世纪最伟大的技能</a>。也就是说，这种能力是：</p><ul><li>从不确定中创造确定性</li><li>从无意义中创造意义</li><li>从混乱中创造清晰</li><li>从分心中创造专注</li><li>从噪音中创造信号</li><li>从无到有创造事物</li><li>从失败中创造成功</li><li>从挣扎中创造意义</li><li>从死亡中创造生命</li><li>从消极中创造积极</li></ul><p><em>这个要点列表就是通向你定义中成功的路径。</em></p><p>大自然具有创造力。你具有创造力。上帝具有创造力。宇宙具有创造力。</p><p>我们的潜意识储存了各种信息，这些信息是根据我们通过感官接触到的事物加工而成的。就像在你可以用显意识将它们连接起来之前，先收集这些点滴一样。</p><p>创造是一个塑造、控制和为意识赋予秩序的过程（可以通过潜意识来触及）。到了那个阶段，我们就可以通过感官将这份礼物带给世界。</p><p>视觉、听觉、味觉、触觉、嗅觉，当然还有极少数人能利用的第六感：</p><p><em>觉察力。</em></p><p>我们的潜意识储存了我们生活中某个时刻觉察到的一切事物。</p><p>这就是创造力的基础——从无尽的深处提取信息、建立连接并解决问题的能力。</p><p><em>创造力就是从混乱中创造清晰。</em></p><p><em>创造 + 清晰 = 创造力。</em></p><p><img src="'+r+'" alt=""></p><p>为现代问题提供创造性的解决方案，就是你赚大钱的方式。</p><p>难怪掌握创造力的人寥寥无几。当我们在18岁被学校系统推入社会时，我们所觉察到的东西少之又少。每个人都在按吩咐做事——因为这是他们唯一知道的事情——而不是去探索未知并做出新的发现。去拓展他们的思维、觉察力和意识。</p><p>我们的现实是通过外部塑造的，而不是通过内在创造我们自己的现实。</p><p>活在当下或“感受当下”并不是那些追求灵修的人的专利。它是过上充满喜悦、创造力和奇迹的生活的必需品。当下正是我们连接无限（或者说上帝之源、宇宙，或是任何其他我们无法用传统五感去把握的智慧的诠释）的途径。</p><p>作为一个创作者，你的工作是通过潜入未知来拓展你的觉察力，提升你的意识。</p><p>把你对未知的探索看作是一项收集点滴的任务。当创造的时刻到来时，你带着连接这些点滴的意图，接入那个无限的场域。</p><p>当你的注意力是不自觉且狭隘的时候，你无法发挥你的创造力。</p><p>当你的注意力是自觉且开放的时候，你就能充分发挥你的创造力。</p><p><img src="'+a+'" alt=""></p><p>我们可以就此探讨一整天的哲学，但我想给你一些实际的步骤，教你如何运用创造力，在未来的十年里蓬勃发展。</p><h2 id="创造力本身并没有内在价值" tabindex="-1">创造力本身并没有内在价值 <a class="header-anchor" href="#创造力本身并没有内在价值" aria-label="Permalink to &quot;创造力本身并没有内在价值&quot;">​</a></h2><p>你可以花上6位数去拿一个艺术编篮子的博士学位——但如果你不了解人类认为什么是真正有价值的，你永远无法靠这个职业谋生。</p><p>为了提升你创造力的感知价值，有些技能是必须学习的（比如你如何拓展自己的觉察力/意识）。</p><p>问题就在这里，价值是由感知决定的。你认为有价值的东西，在另一个人眼里可能就是一堆垃圾。</p><p>你必须研究人类认知的各个方面，这绝对是至关重要的：</p><ul><li>讲故事</li><li>心理学</li><li>灵性</li><li>哲学</li><li>营销</li><li>销售</li><li>品牌建设</li><li>说服力</li><li>设计或视觉叙事</li><li>色彩理论</li><li>吸引注意力</li><li>你自己（自我认知）</li></ul><p>只要研究其中<strong>一项</strong>，你就会接触到<strong>所有</strong>这几项，并开辟出通向未知的独特路径。它们本质上是同一种东西，只是在不同的感知视角下被审视，并通过独特的感官组合被感知。</p><p>人类认知是一座每个人都必须征服的冰山。为什么？因为你需要了解如何传达你创造力的价值。如果你想赚钱，你就必须玩转金钱游戏。不要让你的自负阻碍了你培养沟通技能。如果你想建立起创造性收入，它们是必不可少的。</p><p>你在这座精通之冰山中潜得越深，生活就会越顺利地向你倾斜。从最实用于分发你价值的那些开始——<strong>营销、品牌建设、说服力和销售</strong>。</p><p>它们是将任何技能变现的燃料。如果你想要卖出一个创造性的解决方案，你需要能够吸引人们来关注这个解决方案。换句话说，你需要流量和分发渠道。你可以通过<a href="https://thedankoe.com/the-future-of-work-will-be-play/" target="_blank" rel="noreferrer">建立受众群、建立杠杆、以及建立其他分发网络</a>（比如电子邮件列表）来实现这一点。还有其他诸如付费广告和媒体购买的方法——但那些只有在你的创造性解决方案已经能卖得出去时才有意义。</p><p><em>你如何学习这些技能？</em></p><p>和学习其他任何技能一样——但是大多数人都不擅长学习：</p><p><strong>1) 将自己沉浸在一个与你试图学习的技能相关的信息回音壁中。</strong></p><p>在整整1个月的时间里，只消费与你试图学习的内容相关的信息。</p><p>买1本能全面概述该主题各个方面的书。买一门来自该主题专家的课程，他们已经将信息浓缩成了你需要了解的精华。关注相关的博客、播客、社交媒体账号，以及所有你能找到的资源。</p><p>无论你去哪里，你都要让自己暴露在所关注主题的方方面面中。<em>你要在你所潜入的精通之冰山中获得觉察力——去收集点滴。</em></p><p><strong>2) 开启一个具有潜在盈利能力的个人项目。</strong></p><p>当我学编程时，每一个老师都在反复强调一条建议：</p><p><em>走出教程地狱。</em></p><p>当然没人听这个建议。他们害怕潜入真正的未知。</p><p>为什么一个人要在开启后完全不知道该怎么做（甚至有时根本不知道该怎么开启）的情况下，去启动一个个人项目呢？</p><p>这恰恰就是你应该开启一个的原因。</p><p>因为它能让你的<em>潜意识</em>问题变成<em>显意识</em>问题——<strong>而且非常快</strong>。</p><p><strong>3) 拥抱混乱，并明白没有任何值得拥有的东西是可预测的。</strong></p><blockquote><p>专有知识是通过追求你真正的求知欲和热情来找到的，而不是去追逐当下的任何热点。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1002105081855016961?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 31, 2018</a></p></blockquote><p>通过探索未知来理顺意识，就是你寻找专有知识的方式。在这封信的语境中——专有知识就是一个创造性的解决方案，它是你通过自我教育和建立个人项目来收集和连接各个点滴而找到的。</p><p>通过构建你自己的<a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">与你试图实现的愿景相关的目标层级</a>，你将体验到那些<a href="https://thedankoe.com/if-you-feel-lost-understand-these-3-phases-of-life/" target="_blank" rel="noreferrer">人生阶段</a>，它们会教会你99%的人无法接触到的一课。</p><p>在这里，一致性和持久力是关键。</p><p>就算从零开始重头来过也没关系。</p><p>但如果你全盘放弃这条非传统之路，那就有关系了。</p><p>当你感到怀疑时，休息一下，反思你穿越未知去寻找有意义生活的探索之旅。</p><h2 id="_3点商业模式" tabindex="-1">3点商业模式 <a class="header-anchor" href="#_3点商业模式" aria-label="Permalink to &quot;3点商业模式&quot;">​</a></h2><p>你要开启的第一个具有高盈利潜力的个人项目，就是在社交媒体上打造个人品牌。</p><p>这已不再是可选项。你天生就是一名创作者。雇主现在正根据个人的公开简历（即个人品牌）来雇佣员工。市场现在没有，也永远不会饱和。我们回到了公元前5世纪，权力重新回到了个人手中，而不是组织或公司手里。随着大量想法和信息的涌入，不确定性和焦虑随之而来——这需要由个人来承担起构建自己生活的责任。而不是让宗教、企业文化或其他组织来为你的人生创造确定性。</p><blockquote><p>最好的工作既不是通过法令颁布的，也不是靠学位获得的。它们是持续学习者在自由市场中的创造性表达。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1090363813721862144?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">January 29, 2019</a></p></blockquote><p>为什么我如此坚定地要打造个人品牌？因为建立受众群并打造杠杆，是我为自己做过的最伟大的事情。</p><p><em>你可以在现实世界中练习任何具有创造性或有市场价值的技能。</em></p><p>想学文案写作和说服力？遵循上述快速学习的3个步骤，然后通过写邮件和发推文来练习。</p><p>想学习电子邮件营销、网页设计、销售或任何其他技能？建立一个邮件列表，搭建一个个人网站，给人们发私信拉他们打销售电话，以此来提高你个人品牌的价值（顺便也能在此过程中赚点钱）。</p><p>我扯得有点远了，让我们来点实际的。以下是（针对个人品牌的）3点商业模式：</p><p><strong>1) 创办一份每周通讯。</strong></p><p>为什么？因为大多数人都在玩短内容的游戏，却没有任何权威性可言。</p><p>权威来自于深度和专业知识。有什么比将高质量的电子报（newsletter）作为你业务的主要支柱更好地建立这种权威的方法呢？</p><p>我95%的销售额都来自我的长内容。它建立起的信任是其他人无法匹敌的。</p><p><strong>2) 开通一个 Twitter 账号。</strong></p><p>为什么？</p><ul><li>你不必露脸（如果你不想的话）</li><li>你不必做花哨的设计</li><li>你不必花上几个小时来创作内容</li></ul><p>你需要的只是半个脑子和打字的能力。</p><p>任何人都能写下不到280个字符，然后按下“发送推文”。</p><p>Twitter 的其他好处：</p><ul><li>转推（retweet）可以说是最强大的分享功能——如果你能与他人建立联系，并利用转推借力他们的受众（leverage），你就能快速增长。</li><li>你可以在任何地方发布链接——这意味着在推广你的产品和电子报（为了产生更多销售）方面，你有更多的创作潜力。</li><li>你可以将每周的电子报浓缩成一个推特长文（thread）——长文是你快速获得粉丝的方式。</li><li>没人在乎专业性。如果要我押注哪个平台会成为创作者经济（creator economy）的中心，那就是 Twitter（看看大家是如何把推文复制粘贴到其他平台的，它们通常比花了几个小时创作的帖子更容易疯传）。</li><li>你可以快速测试想法，因为创作 Twitter 内容花不了多少时间。如果一条推文表现很好，那意味着把它做成 YouTube 视频、产品、服务、播客节目、文章或 Instagram 帖子也一样会大受欢迎。</li></ul><p>这完全是零门槛的。</p><p><strong>3) 一个可供迭代的创造性解决方案。</strong></p><p>开始赚钱最简单的方法，就是开展与你的专业技能相关的服务业务。</p><p>开始时你可以免费帮助别人，取得一些成果，然后开始为一个包含4次咨询电话的套餐收取500到1000美元。</p><p>擅长 Web 开发？那就为开发者写内容，与他们建立联系，并收费指导他们正在构建的项目。</p><p>擅长营销？那就为创作者（creators）写内容，与他们建立联系，并针对他们营销上的任何环节提供收费咨询。</p><p>这样的例子不胜枚举——你可以用任何技能来做这件事。我认识一些做大麻疗法的人，还有一些在网上做泰拳教练的人。我也见过提供冲浪课程和指导的人。</p><p>这有一个循序渐进的过程。</p><p>你开始收集各种点滴经验，这些经验将转化为一个你可以高价出售的创造性解决方案或系统。</p><p>这就是大多数人犯错的地方——当他们根本不知道如何创建一个能带来结果（并让你脱颖而出）的独特系统时，他们就想直接去卖 5000 美元的教练套餐，或者每月 30000 美元的营销预付金服务。</p><p>我自己探索出来的一个独特解决方案的例子（我可以为此每月收费5千美元以上）：</p><p>当大家都在试图推销销售漏斗、线索生成（lead generation）以及其他现在极其常见的东西时——我对所有这些都有了足够的经验和实践。</p><p>我最近创建了一个内容生态系统（我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中会教授这个），它能吸引销售又不会显得过于推销。它让你专注于你热爱的事情（制作高质量内容），并简化了推广、社交媒体增长和建立权威的流程。这比什么“以转化为中心的网站”、销售漏斗或线索生成要诱人十倍——我已经把它们全都融入到我的内容生态系统里了。</p><p>（我不是说以转化为中心的网站或销售漏斗不好。它们是阶梯的一部分。只是如果没有实践和迭代，你就无法收取你想要的高昂价格）。</p><p>顺着阶梯一步步往上爬。</p><ul><li>专注于免费帮助人们以了解他们的问题。</li><li>开始研究、写作并创造解决这些问题的方案。</li><li>开始用这个解决方案收取低廉的咨询或自由职业服务费。</li><li>继续完善你的解决方案并取得更多成果</li><li>提高你的价格</li><li>在做所有这些的同时，你也在积累受众——客户会主动找上门来，你也有了推出产品的潜力</li><li>你可以将你创建的系统打包成数字产品，做好营销，并开始完全掌控你的时间和精力</li></ul><p>我可以继续说下去——但如果你还没开始，那对你来说就毫无意义。站在落后你两三步的人的视角进行教学是种常见的做法。如果我告诉你我现在在做什么，而你甚至还没有开始——那你听了也只会是一头雾水。</p><p>在游戏中，你必须达到特定的等级才能学习特定的特质、获取高级装甲并接取更具挑战性的任务。</p><p><em>别总想着在 10 级的时候就获得 100 级的结果。</em></p><p>从今天开始，一头扎进未知之中吧。开始在现实世界中去赚取你的经验值（XP）。</p><p>—— Dan Koe</p><p><strong>本周动态</strong></p><p>Digital Economics 的提前报名<strong>将于今晚美国东部时间晚上7点结束。</strong></p><p>如果你想报名参加一项针对未来创作者、营销人员和一人企业创业者（solopreneurs）的加速教育（同时了解我们在本封信中谈到的所有事情的来龙去脉）——<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">请在今晚7点之前，加入已经报名6月班的另外57名学生的行列。</a></p><p>新的 YouTube 视频将于明天早上发布——这将是一段 45 分钟深入探讨创作金字塔（Creation Pyramid）的视频。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">在这里订阅并打开通知来获取它。</a></p><p>Joey 在 MMHQ 发布了一个培训，教你如何使用 Convertkit 开启你的电子报。</p><p><a href="https://modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">Koe Letter 读者只需花费 5 美元即可加入。</a></p><hr><p><a href="/en/letters/how-to-make-money-as-a-creative-on-the-internet">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',119))])}const T=o(h,[["render",f]]);export{v as __pageData,T as default};
